Status 😀 — résumé de café:
fn café(naïve: &str) -> usize {
    // élève: compte les caractères, pas les octets
    let résumé = naïve.chars().filter(|c| !c.is_whitespace()).count();
    if résumé > 64 {
        eprintln!("trop long: {} — coupe à 64 ☕", résumé);
    }
    résumé.min(64)
}

fn bonjour() -> &'static str {
    "héllo wörld ☃"
}

